fn frame(t: i32) {
    host::display::clear(0x0b0b10);
    if host::display::state_get(0) == 0 {
        host::display::state_set(1, host::net::open("wss://relay.example.net/inbox"));
        host::display::state_set(0, 1);
    }
    let h: i32 = host::display::state_get(1);
    host::display::draw_string(60, 60, "INBOX DRAIN", 0xffffff, 2);
    if h < 0 {
        host::display::draw_string(60, 120, "NO SOCKET", 0xbb3333, 2);
        host::display::draw_string(60, 160, "OPEN RETURNED -1", 0x777777, 1);
    } else {
        let mut got: i32 = host::net::poll(h, 4096, 200);
        while got > 0 {
            host::display::state_set(2, host::display::state_get(2) + 1);
            host::display::state_set(3, got);
            got = host::net::poll(h, 4096, 200);
        }
        host::display::draw_string(60, 130, "MESSAGES", 0x888888, 1);
        host::display::draw_number(60, 150, host::display::state_get(2), 0x66ddff, 4);
        host::display::draw_string(60, 220, "LAST PAYLOAD BYTES", 0x888888, 1);
        host::display::draw_number(60, 240, host::display::state_get(3), 0xffffff, 4);
        if host::net::status(h) == 1 {
            host::display::fill_rect(60, 320, 12, 12, 0x22bb44);
            host::display::draw_string(84, 322, "OPEN", 0x22bb44, 1);
        } else {
            host::display::fill_rect(60, 320, 12, 12, 0xaa7700);
            host::display::draw_string(84, 322, "NOT OPEN", 0xaa7700, 1);
        }
    }
    host::display::present();
}
